answer = []
for source in sources:
    number = source['number']
    fragment = 'proposed-1466-A.xml' if number == '1466 A' else 'proposed-1607-bis.xml'
    item = {key: source[key] for key in ('code_id', 'source_id', 'source_sha256', 'number')}
    item['proposed_xml'] = Path(fragment).read_text().strip()
    item.update(metadata[number])
    item['status'] = 'rewrite_draft'
    item['change_type'] = 'normative_reduction'
    item['reform_policy_id'] = 'editorial_direction_2026_10_19'
    answer.append(item)

Path('answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2) + '\n')
